/*
 * A157452  Number generated by regarding the numbers in row n of A003983 as
 *          digits of a base n number.
 * https://oeis.org/A157452
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) = FromDigits[ Table[ Min[1 + m, 1 + (n - 1 - m)], {m, 0, n
 *            - 1}], n ]
 * Range:     u8 n <= 4, u16 n <= 6, u32 n <= 10, u64 n <= 16, u128 n <= 18,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* For n ≥ 1, a(n) is the integer represented by the digits d_m = min(m+1, n‑m) in base n. */

#include <stdint.h>

seq_t a(idx_t n)
{
    seq_t value = 0;
    for (idx_t m = 0; m < n; ++m) {
        /* Compute the digit for position m (0‑based). */
        idx_t up   = m + 1;
        idx_t down = n - m;
        seq_t digit = (seq_t)(up < down ? up : down);
        /* Accumulate in base n. */
        value = value * (seq_t)n + digit;
    }
    return value;
}
